const listEquipmentAllocations = `-- name: ListEquipmentAllocations :many
SELECT a.id, a.uuid, a.quantity, a.kind, a.status, a.starts_at, a.ends_at, a.expires_at, a.ref_type, a.ref_uuid,
    a.note, a.released_at, a.release_reason, a.created_at, a.updated_at, a.branch_id,
    e.uuid AS extra_uuid, e.code AS extra_code, e.name AS extra_name,
    b.uuid AS branch_uuid, b.code AS branch_code, b.name AS branch_name,
    va.uuid AS vehicle_allocation_uuid,
    u.uuid AS actor_uuid, u.name AS actor_name, u.surname AS actor_surname, u.email AS actor_email
FROM equipment_allocations a
JOIN extras e ON e.organization_id = a.organization_id AND e.id = a.extra_id
JOIN branches b ON b.organization_id = a.organization_id AND b.id = a.branch_id
LEFT JOIN vehicle_allocations va ON va.organization_id = a.organization_id AND va.id = a.vehicle_allocation_id
LEFT JOIN users u ON u.id = a.created_by
WHERE a.organization_id = $1
  AND ($2::bigint[] IS NULL OR a.branch_id = ANY($2::bigint[]))
  AND ($3::bigint IS NULL OR a.extra_id = $3::bigint)
  AND ($4::uuid[] IS NULL OR b.uuid = ANY($4::uuid[]))
  AND ($5::text[] IS NULL OR a.status = ANY($5::text[]))
  AND ($6::text[] IS NULL OR a.kind = ANY($6::text[]))
  AND (
    $7::text IS NULL
    OR e.code ILIKE '%' || $7 || '%'
    OR e.name ILIKE '%' || $7 || '%'
    OR b.name ILIKE '%' || $7 || '%'
    OR a.note ILIKE '%' || $7 || '%'
  )
ORDER BY
  CASE WHEN $8::text = 'starts_at' AND NOT $9::boolean THEN a.starts_at END ASC,
  CASE WHEN $8::text = 'starts_at' AND $9::boolean THEN a.starts_at END DESC,
  CASE WHEN $8::text = 'ends_at' AND NOT $9::boolean THEN a.ends_at END ASC,
  CASE WHEN $8::text = 'ends_at' AND $9::boolean THEN a.ends_at END DESC,
  CASE WHEN $8::text = 'quantity' AND NOT $9::boolean THEN a.quantity END ASC,
  CASE WHEN $8::text = 'quantity' AND $9::boolean THEN a.quantity END DESC,
  CASE WHEN $8::text = 'created_at' AND NOT $9::boolean THEN a.created_at END ASC,
  CASE WHEN $8::text = 'created_at' AND $9::boolean THEN a.created_at END DESC,
  a.id DESC
LIMIT $11 OFFSET $10
`

